using System.Diagnostics;
using System.Runtime.InteropServices;
using TextAnalysis;

// Build representative text (~1000 words)
var wordPool = new string[]
{
    "the", "quick", "brown", "fox", "jumps", "over", "the", "lazy", "dog",
    "and", "then", "runs", "across", "the", "wide", "open", "field",
    "performance", "benchmarking", "is", "important", "for", "understanding",
    "how", "code", "behaves", "under", "different", "runtime", "versions",
    "dotnet", "framework", "provides", "excellent", "tooling", "to", "measure"
};
var rng = new Random(42);
var sb = new System.Text.StringBuilder();
for (int i = 0; i < 1000; i++)
{
    if (i > 0) sb.Append(' ');
    sb.Append(wordPool[rng.Next(wordPool.Length)]);
}
var text = sb.ToString();
var analyzer = new TextAnalyzer(text);

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Text: {analyzer.WordCount} words");
Console.WriteLine();

const int warmupIterations = 500;
const int measuredIterations = 5000;

// Warmup + measure helper
void Benchmark(string name, Action action)
{
    // Warmup
    for (int i = 0; i < warmupIterations; i++) action();

    // Collect multiple rounds for statistics
    const int rounds = 5;
    double[] roundNs = new double[rounds];
    for (int r = 0; r < rounds; r++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < measuredIterations; i++) action();
        sw.Stop();
        roundNs[r] = (double)sw.ElapsedTicks / Stopwatch.Frequency * 1_000_000_000 / measuredIterations;
    }

    Array.Sort(roundNs);
    double median = roundNs[rounds / 2];
    double min = roundNs[0];
    double max = roundNs[rounds - 1];
    Console.WriteLine($"  {name,-25} median: {median,10:F1} ns   min: {min,10:F1} ns   max: {max,10:F1} ns");
}

Console.WriteLine("Benchmarks (lower is better):");
Benchmark("AverageWordLength", () => analyzer.AverageWordLength());
Benchmark("WordLengthHistogram", () => analyzer.WordLengthHistogram());
Benchmark("UniqueWordCount", () => analyzer.UniqueWordCount());

